mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM ACCOUNT account_row
             INNER JOIN CODEF_CONNECTION connection_row
                        ON connection_row.codef_connection_id = account_row.codef_connection_id
    WHERE account_row.user_id = #{userId}
      AND connection_row.user_id = #{userId}
      AND connection_row.provider = #{provider}
)

mapper.delete:
DELETE FROM ACCOUNT
WHERE user_id = #{userId}
  AND codef_connection_id IN (
      SELECT codef_connection_id FROM CODEF_CONNECTION WHERE provider = #{provider}
  )
